<h1><?= te('Documents and acknowledgements') ?></h1><p class="sub"><?= te('Versioned text, authenticated signer, timestamp and document hash. Formal I-9/W-4 and regulated signature-provider workflows are separate integrations.') ?></p><?php if(!$isWorker): ?><form class="card" method="post"><?= csrf_field() ?><input type="hidden" name="do" value="issue"><label><?= te('Worker') ?></label><select name="placement_id"><?php foreach($crew as $c): ?><option value="<?= (int)$c['id'] ?>"><?= e($c['full_name']) ?></option><?php endforeach; ?></select><label><?= te('Document title') ?></label><input name="title" required maxlength="190"><label><?= te('Document text to acknowledge') ?></label><textarea name="document_text" required></textarea><button class="btn"><?= te('Issue document') ?></button></form><?php endif; ?><?php foreach($docs as $d): ?><div class="card"><h2><?= e($d['title']) ?> · <?= e($d['full_name'] ?? '') ?></h2><p><?= nl2br(e($d['document_text'])) ?></p><p class="small muted">SHA-256: <?= e($d['document_hash']) ?></p><?php if($isWorker && $d['status']==='pending'): ?><form method="post"><?= csrf_field() ?><input type="hidden" name="do" value="sign"><input type="hidden" name="document_id" value="<?= (int)$d['id'] ?>"><label><?= te('Full name') ?></label><input name="signer_name" required maxlength="190"><label><input type="checkbox" name="consent" required style="width:auto"> <?= te('I have read this document and intend to acknowledge it using my typed name.') ?></label><button class="btn"><?= te('Sign acknowledgement') ?></button></form><?php else: ?><p><?= e($d['status'].' · '.$d['signer_name'].' · '.$d['signed_at']) ?></p><?php endif; ?></div><?php endforeach; ?>